fn hash(seed: i32) -> i32 {
    let mut h: i32 = seed * 747796405 + 2891336453;
    h = (h >> 16) ^ h;
    if h < 0 { h = 0 - h; }
    h
}

fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    if host::display::state_get(0) == 0 {
        host::display::state_set(0, 1);
        host::display::state_set(1, 0);
    }
    let round: i32 = host::display::state_get(10);
    let fx: i32 = hash(round + 1) % (w - 20);
    let mut fy: i32 = host::display::state_get(1);
    fy = fy + 4;
    let mut px: i32 = host::display::pointer_x() - 30;
    if px < 0 { px = 0; }
    if px > w - 60 { px = w - 60; }
    if fy > h - 28 {
        if fx + 20 > px && fx < px + 60 {
            host::display::state_set(11, host::display::state_get(11) + 1);
        } else {
            host::display::state_set(12, host::display::state_get(12) + 1);
        }
        host::display::state_set(10, round + 1);
        fy = 0;
    }
    host::display::state_set(1, fy);
    host::display::clear(0x000010);
    host::display::fill_rect(fx, fy, 20, 20, 0xffdd00);
    host::display::fill_rect(px, h - 12, 60, 10, 0xffffff);
    host::display::draw_string(8, 8, "SCORE", 0x808080, 1);
    host::display::draw_number(52, 8, host::display::state_get(11), 0x00ff00, 1);
    host::display::draw_string(100, 8, "DROP", 0x808080, 1);
    host::display::draw_number(140, 8, host::display::state_get(12), 0xff4040, 1);
    host::display::present();
}
